#!/usr/bin/env python
"""Setup script for sbmlsim."""
from setuptools import setup  # type: ignore


if __name__ == "__main__":
    setup(version="0.2.2")

try:
    from setuptools import setup
except ImportError:
    from distutils.core import setup

import distutils.cmd
from setuptools import find_packages
import sys,os,re

def read(fname):
    return open(os.path.join(os.path.dirname(__file__), fname)).read()

def strip_rc(version):
    return re.sub(r"rc\d+$", "", version)

def check_versions(min_versions):
    """
    Check versions of dependency packages
    """
    from distutils.version import StrictVersion

    try:
        import scipy
        spversion = scipy.__version__
    except ImportError:
        raise ImportError("mtSet requires scipy")

    try:
        import numpy
        npversion = numpy.__version__
    except ImportError:
        raise ImportError("mtSet requires numpy")

    try:
        import pandas
        pandasversion = pandas.__version__
    except ImportError:
        raise ImportError("mtSet requires pandas")

    #match version numbers
    try:
        assert StrictVersion(strip_rc(npversion)) >= min_versions['numpy']
    except AssertionError:
        raise ImportError("Numpy version is %s. Requires >= %s" %
                (npversion, min_versions['numpy']))
    try:
        assert StrictVersion(strip_rc(spversion)) >= min_versions['scipy']
    except AssertionError:
        raise ImportError("Scipy version is %s. Requires >= %s" %
                (spversion, min_versions['scipy']))
    try:
        assert StrictVersion(strip_rc(pandasversion)) >= min_versions['pandas']
    except AssertionError:
        raise ImportError("pandas version is %s. Requires >= %s" %
                (pandasversion, min_versions['pandas']))

if __name__ == '__main__':
    min_versions = {
        'numpy' : '1.6.0',
        'scipy' : '0.9.0',
        'pandas' : '0.12.0',
        'scons' : '2.1.0',
                   }
    check_versions(min_versions)

    setup(
        name = 'mtSet',
        version = '0.1',
        author = 'Francesco Paolo Casale, Barbara Rakitsch, Oliver Stegle',
        author_email = "casale@ebi.ac.u, rakitsch@ebi.ac.uk, stegle@ebi.ac.uk",
        description = ('Efficient linear mixd model set tests'),
        url = "https://github.com/PMBio/mtSet",
        long_description = read('README.md'),
        license = 'BSD',
        keywords = 'linear mixed models, GWAS, QTL',
        scripts = ['mtSet/bin/mtSet_analyze'],
        #packages = ['mtSet'],
        packages = find_packages(),
        install_requires=['scipy>=0.13', 'numpy>=1.6', 'matplotlib>=1.2', 'nose', 'pandas'],
        )

from setuptools import setup

if __name__ == '__main__':
    readme = open('README.md').read()
    try:
        import pypandoc
        long_description = pypandoc.convert_text(
            readme, 'rst', format='markdown_github')
    except (ImportError, RuntimeError, OSError):
        long_description = readme

    setup(long_description=long_description,
          entry_points = {
              'console_scripts': [
                  'runAssociation=limmbo.bin.runAssociation:entry_point',
                  'runVarianceEstimation=limmbo.bin.runVarianceEstimation:entry_point'
                  ]
              }
          )

#!/usr/bin/env python

import os
import shutil


def clean_gcdas():
    for dirpath, dirnames, filenames in os.walk('.'):
        for f in filenames:
            if f.endswith('.gcda'):
                os.unlink(os.path.join(dirpath, f))


def setup_python_coverage():
    if os.path.exists('coverage'):
        shutil.rmtree('coverage')
    os.mkdir('coverage')
    with open('coverage/sitecustomize.py', 'w') as fh:
        fh.write("""
import coverage
import atexit
import os

def _our_abs_file(self, filename):
    return os.path.normcase(os.path.abspath(filename))
if hasattr(coverage.files, 'FileLocator'):
    coverage.files.FileLocator.abs_file = _our_abs_file

_cov = coverage.coverage(branch=True, data_suffix=True, auto_data=True,
                         data_file='%s')
_cov.start()

def _coverage_cleanup(c):
    c.stop()
atexit.register(_coverage_cleanup, _cov)
""" % os.path.abspath('coverage/.coverage'))
    for dep in os.listdir('src/dependency'):
        dst = 'src/dependency/%s/sitecustomize.py' % dep
        if os.path.exists(dst):
            os.unlink(dst)
        os.symlink(os.path.abspath('coverage/sitecustomize.py'), dst)


def main():
    clean_gcdas()
    setup_python_coverage()


if __name__ == '__main__':
    main()

#!/usr/bin/env python

import os
import shutil


def clean_gcdas():
    for dirpath, dirnames, filenames in os.walk('.'):
        for f in filenames:
            if f.endswith('.gcda'):
                os.unlink(os.path.join(dirpath, f))


def setup_python_coverage():
    if os.path.exists('coverage'):
        shutil.rmtree('coverage')
    os.mkdir('coverage')
    open('coverage/sitecustomize.py', 'w').write("""
import coverage
import atexit
import os

_cov = coverage.coverage(branch=True, data_suffix=True, auto_data=True,
                         data_file='%s')
_cov.start()

def _coverage_cleanup(c):
    c.stop()
atexit.register(_coverage_cleanup, _cov)
""" % os.path.abspath('coverage/.coverage'))


def main():
    clean_gcdas()
    setup_python_coverage()


if __name__ == '__main__':
    main()

"""Define some common setup blocks which benchmarks can reuse."""

import enum

from core.api import GroupedSetup
from core.utils import parse_stmts


_TRIVIAL_2D = GroupedSetup(
    r"x = torch.ones((4, 4))",
    r"auto x = torch::ones({4, 4});"
)


_TRIVIAL_3D = GroupedSetup(
    r"x = torch.ones((4, 4, 4))",
    r"auto x = torch::ones({4, 4, 4});"
)


_TRIVIAL_4D = GroupedSetup(
    r"x = torch.ones((4, 4, 4, 4))",
    r"auto x = torch::ones({4, 4, 4, 4});"
)


_TRAINING = GroupedSetup(*parse_stmts(
    r"""
        Python                                   | C++
        ---------------------------------------- | ----------------------------------------
        # Inputs                                 | // Inputs
        x = torch.ones((1,))                     | auto x = torch::ones({1});
        y = torch.ones((1,))                     | auto y = torch::ones({1});
                                                 |
        # Weights                                | // Weights
        w0 = torch.ones(                         | auto w0 = torch::ones({1});
            (1,), requires_grad=True)            | w0.set_requires_grad(true);
        w1 = torch.ones(                         | auto w1 = torch::ones({1});
            (1,), requires_grad=True)            | w1.set_requires_grad(true);
        w2 = torch.ones(                         | auto w2 = torch::ones({2});
            (2,), requires_grad=True)            | w2.set_requires_grad(true);
    """
))


class Setup(enum.Enum):
    TRIVIAL_2D = _TRIVIAL_2D
    TRIVIAL_3D = _TRIVIAL_3D
    TRIVIAL_4D = _TRIVIAL_4D
    TRAINING = _TRAINING

