def print_success(message=None):
		if message is None:
			sys.stdout.write("OK\n")
		else:
			message = str(message)
			sys.stdout.write(message)
			if not message.endswith("\n"):
				sys.stdout.write("\n")
		sys.stdout.flush()
if __name__ == "__main__":
